import { useEffect, useMemo, useState, type CSSProperties, type ReactNode } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  ApiError,
  api,
  type PlanItem,
  type PlanItemWrite,
  type PlanKind,
  type PlanSnapshot,
  type PlanState,
} from "../api/client";
import { captureSession, isSessionContextActive } from "../session";
import { keys, useProject } from "../state";
import { dateInZone, localDateTimeToUtc } from "../time";
import { Dialog, Link, Notice, ProjectMissing, QueryState, Shell } from "../ui";
import { Avatar, Icon, StatusBadge } from "../workspace-ui";
import { useUnsavedChanges } from "../unsaved-changes";
import "./project-plan.css";

type View = "roadmap" | "hierarchy" | "tasks" | "board" | "milestones" | "calendar";
const views: Array<[View, string]> = [
  ["roadmap", "로드맵"], ["hierarchy", "계층"], ["tasks", "작업"],
  ["board", "보드"], ["milestones", "Milestone"], ["calendar", "월간"],
];
const kinds: PlanKind[] = ["EPIC", "TOPIC", "TASK", "MILESTONE"];
const states: PlanState[] = ["BACKLOG", "READY", "IN_PROGRESS", "BLOCKED", "DONE", "CANCELLED"];
const kindLabel: Record<PlanKind, string> = { EPIC: "EPIC", TOPIC: "TOPIC", TASK: "TASK", MILESTONE: "Milestone" };
const stateLabel: Record<PlanState, string> = { BACKLOG: "백로그", READY: "준비", IN_PROGRESS: "진행 중", BLOCKED: "차단", DONE: "완료", CANCELLED: "취소" };
const defaultTypes: Record<View, PlanKind[]> = {
  roadmap: kinds, hierarchy: ["EPIC", "TOPIC"], tasks: ["TASK"], board: ["TASK"], milestones: ["MILESTONE"], calendar: ["TASK", "MILESTONE"],
};
const effectivePlanTypes = (query: URLSearchParams, view: View) => {
  const selected = (query.get("types") ?? query.get("kind"))?.split(",").filter((value): value is PlanKind => kinds.includes(value as PlanKind)) ?? [];
  return selected.length > 0 ? selected : defaultTypes[view];
};

const randomId = () => typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;
const dateText = (value?: string | null) => value || "날짜 미정";
const itemDates = (item: PlanItem) => [item.targetStart, item.targetEnd, item.deadline].filter(Boolean) as string[];
const pathFor = (item: PlanItem, byId: Map<string, PlanItem>) => {
  const path: string[] = [];
  let current: PlanItem | undefined = item;
  const seen = new Set<string>();
  while (current && !seen.has(current.id)) {
    path.unshift(current.title); seen.add(current.id);
    current = current.parentId ? byId.get(current.parentId) : undefined;
  }
  return path.join(" / ");
};
const parentPathFor = (item: PlanItem, byId: Map<string, PlanItem>) => item.parentId ? pathFor(byId.get(item.parentId) ?? item, byId) : "프로젝트 루트";
const emptySummary = { taskCount: 0, doneCount: 0, blockedCount: 0, overdueCount: 0, unplannedCount: 0, unassignedCount: 0, progressPercent: null, forecastStart: null, forecastEnd: null, forecastState: "EMPTY" as const, outsideTarget: false };
const viewDefaultKind: Record<View, PlanKind> = { roadmap: "TOPIC", hierarchy: "TOPIC", tasks: "TASK", board: "TASK", milestones: "MILESTONE", calendar: "TASK" };
const validParent = (kind: PlanKind, parent?: PlanItem | null) => {
  if (!parent) return kind === "EPIC" || kind === "MILESTONE";
  return kind === "TOPIC" ? parent.kind === "EPIC" : kind === "TASK" || kind === "MILESTONE" ? parent.kind === "EPIC" || parent.kind === "TOPIC" : false;
};
const stateTone: Record<PlanState, "neutral" | "blue" | "amber" | "green" | "red"> = { BACKLOG: "neutral", READY: "blue", IN_PROGRESS: "blue", BLOCKED: "amber", DONE: "green", CANCELLED: "red" };
const stateIcon: Record<PlanState, "clock" | "check" | "draft" | "cancel"> = { BACKLOG: "draft", READY: "clock", IN_PROGRESS: "clock", BLOCKED: "clock", DONE: "check", CANCELLED: "cancel" };
const assigneeText = (item: PlanItem) => item.assigneeName || (item.assigneeId ? `이름 확인 불가 (${item.assigneeId})` : "미배정");
function readQuery() {
  const query = new URLSearchParams(window.location.hash.split("?", 2)[1] ?? "");
  const view = (views.some(([id]) => id === query.get("view")) ? query.get("view") : "roadmap") as View;
  return { query, view };
}
function setQuery(projectId: string, values: Record<string, string | null | undefined>, replace = false) {
  const current = replace ? new URLSearchParams() : new URLSearchParams(window.location.hash.split("?", 2)[1] ?? "");
  Object.entries(values).forEach(([key, value]) => value ? current.set(key, value) : current.delete(key));
  const qs = current.toString();
  window.location.hash = `#/projects/${encodeURIComponent(projectId)}/plan${qs ? `?${qs}` : ""}`;
}
function queryString(query: URLSearchParams, view: View) {
  const allowed = ["state", "includeCancelled", "assigneeId", "unassigned", "scopeId", "from", "to", "q", "label"];
  const apiQuery = new URLSearchParams();
  allowed.forEach((key) => { if (query.has(key)) apiQuery.set(key, query.get(key)!); });
  const selected = effectivePlanTypes(query, view);
  apiQuery.set("kind", selected.join(","));
  return apiQuery.toString();
}
function Summary({ label, summary, filteredCount }: { label: string; summary: PlanSnapshot["summary"]; filteredCount?: number }) {
  return <section className="plan-summary" aria-label={`${label} 요약`}>
    <div><span>{label}</span><strong>{summary.taskCount}</strong><small>실행 TASK</small></div>
    <div><span>완료</span><strong>{summary.doneCount}</strong><small>{summary.progressPercent == null ? "실행 작업 없음" : `${summary.progressPercent}%`}</small></div>
    <div><span>차단</span><strong>{summary.blockedCount}</strong><small>미완료 기준</small></div>
    <div><span>기한 지남</span><strong>{summary.overdueCount}</strong><small>완료 제외</small></div><div><span>미계획</span><strong>{summary.unplannedCount}</strong><small>날짜 부족</small></div><div><span>미배정</span><strong>{summary.unassignedCount}</strong><small>담당자 없음</small></div><div><span>예상 기간</span><strong>{summary.forecastState === "COMPLETE" ? dateText(summary.forecastEnd) : summary.forecastState === "EMPTY" ? "없음" : summary.forecastState === "UNDATED" ? "미정" : "불완전"}</strong><small>{filteredCount === undefined ? "전체 프로젝트" : `필터 항목 ${filteredCount}건`}</small></div>
  </section>;
}

export function ItemBadge({ item }: { item: PlanItem }) {
  const progress = item.summary.progressPercent;
  const person = assigneeText(item);
  return <span className={`plan-badge plan-badge--${item.kind.toLowerCase()}`}><StatusBadge tone={item.kind === "EPIC" ? "neutral" : item.kind === "TOPIC" ? "blue" : item.kind === "TASK" ? "green" : "amber"}>{kindLabel[item.kind]}</StatusBadge><StatusBadge tone={stateTone[item.state]} icon={stateIcon[item.state]}>{stateLabel[item.state]}</StatusBadge><Avatar name={person} /><span className="plan-progress" aria-label={progress == null ? "진행 정보 없음" : `진행률 ${progress}%`}><i style={{ "--progress": `${Math.max(0, Math.min(100, progress ?? 0))}%` } as CSSProperties} />{progress == null ? "진행 정보 없음" : `${progress}%`}</span></span>;
}

function PlanItemRow({ item, byId, canEdit, onOpen, onQuickEdit }: { item: PlanItem; byId: Map<string, PlanItem>; canEdit: boolean; onOpen: (item: PlanItem) => void; onQuickEdit: (item: PlanItem, field: "title" | "state" | "targetStart" | "targetEnd" | "deadline" | "sortOrder", value: string) => void }) {
  const [editing, setEditing] = useState(false);
  const [title, setTitle] = useState(item.title);
  useEffect(() => setTitle(item.title), [item.title]);
  const saveTitle = () => { setEditing(false); if (title.trim() && title.trim() !== item.title) onQuickEdit(item, "title", title.trim()); else setTitle(item.title); };
  return <div className="plan-row" data-kind={item.kind} data-state={item.state}>
    <div className="plan-row-main">
      <ItemBadge item={item} />
      {editing && canEdit ? <span className="inline-editor"><input aria-label={`${item.title} 제목`} value={title} onChange={(e) => setTitle(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") saveTitle(); if (e.key === "Escape") { setTitle(item.title); setEditing(false); } }} autoFocus /><button type="button" onClick={saveTitle}>저장</button><button type="button" onClick={() => { setTitle(item.title); setEditing(false); }}>취소</button></span> : <button className="plan-title" type="button" onClick={() => onOpen(item)}>{item.title}</button>}
      <span className="plan-path">{pathFor(item, byId)}</span>
    </div>
    <span className="plan-assignee">{assigneeText(item)}</span>
    <label className="sr-only" htmlFor={`state-${item.id}`}>상태</label>
    <select id={`state-${item.id}`} aria-label={`${item.title} 상태`} disabled={!canEdit} value={item.state} onChange={(e) => onQuickEdit(item, "state", e.target.value)}>
      {states.map((state) => <option key={state} value={state}>{stateLabel[state]}</option>)}
    </select>
    <span className="plan-dates"><label>시작<input aria-label={`${item.title} 시작일`} type="date" disabled={!canEdit} value={item.targetStart ?? ""} onChange={(e) => onQuickEdit(item, "targetStart", e.target.value)} /></label><label>종료<input aria-label={`${item.title} 종료일`} type="date" disabled={!canEdit} value={item.targetEnd ?? ""} onChange={(e) => onQuickEdit(item, "targetEnd", e.target.value)} /></label><label>마감<input aria-label={`${item.title} 마감일`} type="date" disabled={!canEdit} value={item.deadline ?? ""} onChange={(e) => onQuickEdit(item, "deadline", e.target.value)} /></label></span>
    <span className="plan-row-meta">{item.blockerIds.length ? `차단 ${item.blockerIds.length}` : ""}{item.predecessorIds.length ? ` 선행 ${item.predecessorIds.length}` : ""}</span>
    {canEdit && <button className="text-button plan-edit" type="button" onClick={() => setEditing(true)}>제목 편집</button>}
    <button className="text-button" type="button" onClick={() => onOpen(item)}>세부 정보</button>
  </div>;
}

function ItemEditor({ projectId, item, items, canEdit, initialKind = "TASK", initialParentId = null, initialDraft, recoveryMessage, onClose, onSaved, onForbidden }: { projectId: string; item?: PlanItem | null; items: PlanItem[]; canEdit: boolean; initialKind?: PlanKind; initialParentId?: string | null; initialDraft?: PlanItemWrite; recoveryMessage?: string; onClose: () => void; onSaved: () => void; onForbidden: () => void }) {
  const qc = useQueryClient();
  const creating = !item;
  const [draft, setDraft] = useState<PlanItemWrite>(() => initialDraft ?? (item ? { parentId: item.parentId, kind: item.kind, title: item.title, description: item.description ?? "", assigneeId: item.assigneeId, state: item.state, targetStart: item.targetStart, targetEnd: item.targetEnd, deadline: item.deadline, sortOrder: item.sortOrder, labels: item.labels, predecessorIds: item.predecessorIds, rowVersion: item.rowVersion } : { parentId: initialParentId, kind: initialKind, title: "", description: "", assigneeId: null, state: "BACKLOG", targetStart: null, targetEnd: null, deadline: null, sortOrder: 0, labels: [], predecessorIds: [], requestId: randomId() }));
  const [conflict, setConflict] = useState(false);
  const initialValue = useMemo(() => initialDraft ?? (item ? { parentId: item.parentId, kind: item.kind, title: item.title, description: item.description ?? "", assigneeId: item.assigneeId, state: item.state, targetStart: item.targetStart, targetEnd: item.targetEnd, deadline: item.deadline, sortOrder: item.sortOrder, labels: item.labels, predecessorIds: item.predecessorIds, rowVersion: item.rowVersion } : { parentId: initialParentId, kind: initialKind, title: "", description: "", assigneeId: null, state: "BACKLOG" as PlanState, targetStart: null, targetEnd: null, deadline: null, sortOrder: 0, labels: [], predecessorIds: [], requestId: randomId() }), [initialDraft, initialKind, initialParentId, item]);
  const [saved, setSaved] = useState<PlanItemWrite>(initialValue);
  const [latest, setLatest] = useState<PlanItem | null>(null);
  const [secondaryOpen, setSecondaryOpen] = useState(false);
  const members = useQuery({ queryKey: keys.members(projectId), queryFn: () => api.members(projectId), enabled: canEdit });
  const comparable = (value: PlanItemWrite) => { const { requestId: _requestId, rowVersion: _rowVersion, ...rest } = value; return rest; };
  const dirty = JSON.stringify(comparable(draft)) !== JSON.stringify(comparable(saved));
  const guard = useUnsavedChanges(dirty);
  const mutation = useMutation({ mutationFn: (body: PlanItemWrite) => creating ? api.createPlanItem(projectId, body) : api.updatePlanItem(projectId, item!.id, body), onMutate: captureSession, onSuccess: async (_value, _vars, context) => { if (!isSessionContextActive(context)) return; setSaved(_vars); guard.markSaved(); await qc.invalidateQueries({ queryKey: ["project-plan", projectId] }); onSaved(); }, onError: async (error) => { if (error instanceof ApiError && error.status === 403) onForbidden(); if (error instanceof ApiError && error.status === 409) { setConflict(true); try { const fresh = await api.plan(projectId); setLatest(item ? fresh.items.find((candidate) => candidate.id === item.id) ?? null : null); } catch { /* keep the user's draft when the recovery read fails */ } } } });
  const secondaryError = mutation.error instanceof ApiError && mutation.error.problem.fieldErrors?.some(({ field }) => ["description", "state", "labels", "predecessorIds"].includes(field.replace(/\[.*$|\..*$/g, "")));
  useEffect(() => { if (secondaryError) setSecondaryOpen(true); }, [secondaryError]);
  const update = <K extends keyof PlanItemWrite>(key: K, value: PlanItemWrite[K]) => setDraft((current) => ({ ...current, [key]: value }));
  const save = () => { if (!canEdit || !draft.title.trim() || mutation.isPending) return; mutation.mutate(draft); };
  const close = () => { if (guard.confirmDiscard()) onClose(); };
  return <Dialog open title={creating ? "계획 항목 만들기" : `${item.title} 세부 정보`} onClose={close} labelledBy="plan-editor-title">
    <form onInvalidCapture={(event) => { if ((event.target as HTMLElement).closest(".plan-secondary-fields")) setSecondaryOpen(true); }} onSubmit={(e) => { e.preventDefault(); save(); }}>
      {recoveryMessage && <div className="plan-conflict" role="alert"><strong>다른 구성원이 먼저 변경했다.</strong><p>{recoveryMessage}</p></div>}
      <label>종류<select value={draft.kind} disabled={!canEdit} onChange={(e) => { const next = e.target.value as PlanKind; update("kind", next); if (!validParent(next, items.find((candidate) => candidate.id === draft.parentId))) update("parentId", null); }}>{kinds.map((kind) => <option key={kind} value={kind}>{kindLabel[kind]}</option>)}</select></label>
      <label>제목<input required maxLength={200} value={draft.title} disabled={!canEdit || mutation.isPending} onChange={(e) => update("title", e.target.value)} /></label>
      <label>상위 항목<select value={draft.parentId ?? ""} disabled={!canEdit || draft.kind === "EPIC"} onChange={(e) => update("parentId", e.target.value || null)}><option value="">프로젝트 루트</option>{items.filter((candidate) => candidate.id !== item?.id && validParent(draft.kind, candidate)).map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.title} ({candidate.kind})</option>)}</select></label>
      <label>담당자<select value={draft.assigneeId ?? ""} disabled={!canEdit || members.isPending} onChange={(e) => update("assigneeId", e.target.value || null)}><option value="">미배정</option>{(members.data ?? []).filter((member) => member.role === "MANAGER" || member.role === "MEMBER").map((member) => <option key={member.userId} value={member.userId}>{member.displayName || member.email || member.userId}</option>)}</select></label>
      <div className="plan-form-grid"><label>시작일<input type="date" value={draft.targetStart ?? ""} disabled={!canEdit} onChange={(e) => update("targetStart", e.target.value || null)} /></label><label>종료일<input type="date" value={draft.targetEnd ?? ""} disabled={!canEdit} onChange={(e) => update("targetEnd", e.target.value || null)} /></label><label>마감일<input type="date" value={draft.deadline ?? ""} disabled={!canEdit} onChange={(e) => update("deadline", e.target.value || null)} /></label></div>
      <details className="plan-secondary-fields" open={secondaryOpen} onToggle={(event) => setSecondaryOpen((event.currentTarget as HTMLDetailsElement).open)}><summary>세부 정보</summary><div className="plan-secondary-content"><label>설명<textarea maxLength={10000} value={draft.description} disabled={!canEdit || mutation.isPending} onChange={(e) => update("description", e.target.value)} /></label>
      <label>상태<select value={draft.state} disabled={!canEdit} onChange={(e) => update("state", e.target.value as PlanState)}>{states.map((state) => <option key={state} value={state}>{stateLabel[state]}</option>)}</select></label>
      <label>레이블<input aria-label="레이블" value={draft.labels.join(", ")} disabled={!canEdit} placeholder="쉼표로 구분" onChange={(e) => update("labels", e.target.value.split(",").map((value) => value.trim()).filter(Boolean))} /><small className="help">최대 20개, 각 50자까지 입력한다.</small></label>
      <label>선행 항목<select multiple value={draft.predecessorIds} disabled={!canEdit} onChange={(e) => update("predecessorIds", Array.from(e.target.selectedOptions, (option) => option.value))}>{items.filter((candidate) => candidate.id !== item?.id && (candidate.kind === "TASK" || candidate.kind === "MILESTONE")).map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.title} · {candidate.kind} · {stateLabel[candidate.state]}</option>)}</select><small className="help">같은 프로젝트의 TASK·Milestone을 제목으로 선택한다. 최대 200개.</small></label></div></details>
      {conflict && <div className="plan-conflict" role="alert"><strong>다른 구성원이 변경했습니다.</strong>{latest && <p>최신값: <b>{latest.title}</b> · {stateLabel[latest.state]} · {dateText(latest.targetStart)} – {dateText(latest.targetEnd)}</p>}<p>내 입력은 보존되어 있다. 최신 version으로 재시도하거나 최신값을 적용할 수 있다.</p><button type="button" disabled={!latest || mutation.isPending} onClick={() => { if (latest) { const rebased = { ...draft, rowVersion: latest.rowVersion }; setDraft(rebased); setConflict(false); mutation.mutate(rebased); } }}>내 입력을 최신 version으로 재시도</button><button type="button" onClick={() => { if (latest) setDraft({ parentId: latest.parentId, kind: latest.kind, title: latest.title, description: latest.description ?? "", assigneeId: latest.assigneeId, state: latest.state, targetStart: latest.targetStart, targetEnd: latest.targetEnd, deadline: latest.deadline, sortOrder: latest.sortOrder, labels: latest.labels, predecessorIds: latest.predecessorIds, rowVersion: latest.rowVersion }); setConflict(false); }}>최신값 적용</button><button type="button" onClick={() => setConflict(false)}>내 입력으로 다시 편집</button></div>}
      {mutation.isError && !conflict && <Notice error={mutation.error} />}
      <div className="modal-actions"><button type="button" onClick={close}>취소</button>{canEdit && <button className="button-primary" type="submit" disabled={mutation.isPending}>{mutation.isPending ? "저장 중…" : "저장"}</button>}</div>
    </form>
  </Dialog>;
}

function History({ projectId, itemId, items, members }: { projectId: string; itemId: string; items: PlanItem[]; members: Array<{ userId: string; displayName?: string | null; email?: string | null }> }) {
  const [page, setPage] = useState(0);
  const history = useQuery({ queryKey: ["plan-history", projectId, itemId, page], queryFn: () => api.planHistory(projectId, itemId, page) });
  if (history.isPending) return <p className="help">변경 이력을 불러오는 중…</p>;
  if (history.isError) return <Notice error={history.error} />;
  const itemName = (id?: string | null) => id ? items.find((candidate) => candidate.id === id)?.title || `확인할 수 없는 항목 (${id})` : "프로젝트 루트";
  const actorName = (id: string) => { const member = members.find((candidate) => candidate.userId === id); return member?.displayName || member?.email || `확인할 수 없는 사용자 (${id})`; };
  const describe = (value: Partial<PlanItem> | null) => value ? [value.title !== undefined ? `제목 ${value.title}` : "", value.description !== undefined ? `설명 ${value.description || "없음"}` : "", value.state ? `상태 ${stateLabel[value.state]}` : "", value.parentId !== undefined ? `상위 ${itemName(value.parentId)}` : "", value.targetStart !== undefined || value.targetEnd !== undefined ? `목표 기간 ${dateText(value.targetStart)} – ${dateText(value.targetEnd)}` : "", value.deadline !== undefined ? `마감 ${dateText(value.deadline)}` : "", value.assigneeId !== undefined ? `담당자 ${value.assigneeId ? actorName(value.assigneeId) : "미배정"}` : "", value.labels ? `레이블 ${value.labels.join(", ") || "없음"}` : "", value.predecessorIds ? `선행 ${value.predecessorIds.map(itemName).join(", ") || "없음"}` : ""].filter(Boolean).join(" · ") || "변경 없음" : "없음";
  return <><ol className="plan-history">{history.data.entries.map((entry) => <li key={entry.id}><strong>변경 {entry.version}</strong><time>{entry.occurredAt}</time><span>변경자 {actorName(entry.actorId)}</span><span>{entry.reason || "변경 사유 없음"}</span><details><summary>변경 내용</summary><pre>이전: {describe(entry.before)}{"\n"}이후: {describe(entry.after)}</pre></details></li>)}</ol><div className="pagination"><button type="button" disabled={page === 0} onClick={() => setPage((value) => value - 1)}>최신 이력</button><span>{page + 1}페이지</span><button type="button" disabled={!history.data.hasNext} onClick={() => setPage((value) => value + 1)}>이전 이력</button></div></>;
}

function DetailDialog({ projectId, item, items, members, canEdit, onClose, onEdit, onNavigate }: { projectId: string; item: PlanItem | null; items: PlanItem[]; members: Array<{ userId: string; displayName?: string | null; email?: string | null }>; canEdit: boolean; onClose: () => void; onEdit: () => void; onNavigate: (item: PlanItem) => void }) {
  const [historyOpen, setHistoryOpen] = useState(false);
  if (!item) return null;
  const resolve = (id: string) => items.find((candidate) => candidate.id === id);
  return <Dialog open title={item.title} onClose={onClose} labelledBy="plan-detail-title"><div className="plan-detail"><ItemBadge item={item} /><p>{item.description || "설명이 없습니다."}</p><dl><dt>상위 항목</dt><dd>{item.parentId ? items.find((candidate) => candidate.id === item.parentId)?.title || item.parentId : "프로젝트 루트"}</dd><dt>담당자</dt><dd>{item.assigneeName || item.assigneeId || "미배정"}</dd><dt>기간</dt><dd>{dateText(item.targetStart)} – {dateText(item.targetEnd)}</dd><dt>마감일</dt><dd>{dateText(item.deadline)}</dd><dt>선행</dt><dd>{item.predecessorIds.length ? <span className="plan-link-list">{item.predecessorIds.map((id) => <button key={id} type="button" onClick={() => resolve(id) && onNavigate(resolve(id)!)}>{resolve(id)?.title || id}</button>)}</span> : "없음"}</dd><dt>영향</dt><dd>{item.successorIds.length ? <span className="plan-link-list">{item.successorIds.map((id) => <button key={id} type="button" onClick={() => resolve(id) && onNavigate(resolve(id)!)}>{resolve(id)?.title || id}</button>)}</span> : "없음"}</dd></dl>{item.blockerIds.length > 0 && <p className="plan-warning">선행 작업이 끝나지 않아 차단됨: {item.blockerIds.map((id) => resolve(id)?.title || id).join(", ")}</p>}<div className="modal-actions">{canEdit && <button onClick={onEdit}>편집</button>}<button onClick={() => setHistoryOpen((value) => !value)}>변경 이력</button></div>{historyOpen && <History projectId={projectId} itemId={item.id} items={items} members={members} />}</div></Dialog>;
}

function Roadmap({ items, byId, onOpen }: { items: PlanItem[]; byId: Map<string, PlanItem>; onOpen: (item: PlanItem) => void }) {
  const dated = items.flatMap((item) => [...itemDates(item), item.summary.forecastStart, item.summary.forecastEnd].filter(Boolean) as string[]); const min = dated.sort()[0]; const max = dated.at(-1); const span = min && max ? Math.max(1, (Date.parse(max) - Date.parse(min)) / 86400000 + 1) : 1;
  const geometry = (start?: string | null, end?: string | null) => ({ left: start && min ? ((Date.parse(start) - Date.parse(min)) / 86400000 / span) * 100 : 0, width: start && end ? Math.max(3, ((Date.parse(end) - Date.parse(start) + 86400000) / 86400000 / span) * 100) : 0 });
  return <section className="plan-roadmap" aria-label="로드맵"><div className="plan-legend"><span><i className="legend-target" />합의 목표 기간</span><span><i className="legend-forecast" />TASK 예상 기간</span><span>불완전한 예상 기간은 알려진 경계만 점선으로 표시</span></div><div className="plan-axis"><span>{min || "날짜 미정"}</span><span>{max || "계획 날짜 없음"}</span></div>{items.map((item) => { const start = item.targetStart || item.targetEnd; const end = item.targetEnd || item.targetStart; const target = geometry(start, end); const forecast = item.summary.forecastState === "COMPLETE" ? `${dateText(item.summary.forecastStart)} – ${dateText(item.summary.forecastEnd)}` : item.summary.forecastState === "INCOMPLETE" ? `불완전 · 알려진 범위 ${dateText(item.summary.forecastStart)} – ${dateText(item.summary.forecastEnd)}` : item.summary.forecastState === "UNDATED" ? "날짜 미정" : "실행 작업 없음"; const forecastBar = geometry(item.summary.forecastStart, item.summary.forecastEnd); return <div className="roadmap-row" key={item.id}><div className="roadmap-label"><ItemBadge item={item} /><button type="button" onClick={() => onOpen(item)}>{pathFor(item, byId)}</button></div><div className="roadmap-info"><span><b>목표 기간</b> {dateText(start)} – {dateText(end)}</span><span><b>예상 기간</b> {forecast}{item.summary.outsideTarget ? " · 목표 범위 밖" : ""}</span></div><div className="roadmap-track">{target.width > 0 ? <span aria-label={`목표 기간 ${dateText(start)}부터 ${dateText(end)}까지`} className="roadmap-target" style={{ left: `${target.left}%`, width: `${target.width}%` }} /> : <span className="roadmap-undated">목표 날짜 미정</span>}{forecastBar.width > 0 && <span aria-label={`예상 기간 ${dateText(item.summary.forecastStart)}부터 ${dateText(item.summary.forecastEnd)}까지`} className="roadmap-forecast" style={{ left: `${forecastBar.left}%`, width: `${forecastBar.width}%` }} />}</div></div>; })}</section>;
}

function Hierarchy({ items, byId, showLeaves, onShowLeaves, onOpen, onQuickEdit, canEdit, onScope }: { items: PlanItem[]; byId: Map<string, PlanItem>; showLeaves: boolean; onShowLeaves: (value: boolean) => void; onOpen: (item: PlanItem) => void; onQuickEdit: (item: PlanItem, field: "title" | "state" | "targetStart" | "targetEnd" | "deadline" | "sortOrder", value: string) => void; canEdit: boolean; onScope: (id: string) => void }) {
  const [collapsed, setCollapsed] = useState<Set<string>>(new Set());
  const visibleIds = new Set(items.map((item) => item.id));
  const roots = items.filter((item) => !item.parentId || !visibleIds.has(item.parentId));
  const children = (parentId: string) => items.filter((item) => item.parentId === parentId).sort((a, b) => a.sortOrder - b.sortOrder);
  const branch = (item: PlanItem, depth = 0): ReactNode => { const childRows = children(item.id); const siblings = item.parentId ? children(item.parentId) : roots; const index = siblings.findIndex((candidate) => candidate.id === item.id); const isCollapsed = collapsed.has(item.id); const visibleChildren = showLeaves ? childRows : childRows.filter((child) => child.kind === "EPIC" || child.kind === "TOPIC"); return <div className="plan-tree-node" key={item.id} style={{ "--depth": depth } as CSSProperties}><div className="plan-tree-tools">{childRows.length > 0 && <button type="button" aria-label={`${item.title} 하위 항목 ${childRows.length}개 ${isCollapsed ? "펼치기" : "접기"}`} onClick={() => setCollapsed((current) => { const next = new Set(current); if (next.has(item.id)) next.delete(item.id); else next.add(item.id); return next; })}>{isCollapsed ? "펼치기" : "접기"} ({childRows.length})</button>}<button type="button" onClick={() => onScope(item.id)}>하위 항목 보기</button>{canEdit && <><button type="button" disabled={index <= 0} onClick={() => onQuickEdit(item, "sortOrder", String(siblings[index - 1]?.sortOrder - 1))}>위로 이동</button><button type="button" disabled={index === siblings.length - 1} onClick={() => onQuickEdit(item, "sortOrder", String(siblings[index + 1]?.sortOrder + 1))}>아래로 이동</button>{(item.kind === "EPIC" || item.kind === "TOPIC") && item.state !== "CANCELLED" && <button type="button" onClick={() => { if (window.confirm(`${item.title}만 취소한다. 하위 작업은 변경하지 않는다.`)) onQuickEdit(item, "state", "CANCELLED"); }}>컨테이너 취소</button>}</>}</div><PlanItemRow item={item} byId={byId} canEdit={canEdit} onOpen={onOpen} onQuickEdit={onQuickEdit} />{!isCollapsed && visibleChildren.map((child) => branch(child, depth + 1))}</div>; };
  return <section className="plan-tree" aria-label="EPIC과 TOPIC 계층"><div className="plan-tree-toolbar"><label><input type="checkbox" checked={showLeaves} onChange={(e) => onShowLeaves(e.target.checked)} /> TASK·Milestone도 펼쳐 보기</label><span className="help">기본은 EPIC·TOPIC 중심 계층이다. 검색으로 직접 일치한 하위 항목은 경로와 함께 표시한다.</span></div>{roots.filter((root) => showLeaves || root.kind === "EPIC" || root.kind === "TOPIC" || !!root.parentId).sort((a, b) => a.sortOrder - b.sortOrder).map((root) => branch(root))}</section>;
}

function Tasks({ items, byId, members, onOpen, onQuickEdit, canEdit }: { items: PlanItem[]; byId: Map<string, PlanItem>; members: Array<{ userId: string; role: string; displayName?: string | null; email?: string | null }>; onOpen: (item: PlanItem) => void; onQuickEdit: (item: PlanItem, field: "title" | "state" | "assigneeId" | "targetStart" | "targetEnd" | "deadline" | "sortOrder", value: string) => void; canEdit: boolean }) {
  const [page, setPage] = useState(0); const [sort, setSort] = useState("state"); const [group, setGroup] = useState("none"); const rows = useMemo(() => items.filter((item) => item.kind === "TASK").sort((a, b) => sort === "deadline" ? (a.deadline || "9999").localeCompare(b.deadline || "9999") : sort === "title" ? a.title.localeCompare(b.title) : a.state.localeCompare(b.state) || a.sortOrder - b.sortOrder), [items, sort]); const shown = rows.slice(page * 50, page * 50 + 50);
  useEffect(() => { if (page * 50 >= rows.length) setPage(Math.max(0, Math.ceil(rows.length / 50) - 1)); }, [page, rows.length]);
  const groups = useMemo(() => shown.reduce<Map<string, PlanItem[]>>((all, item) => { const key = group === "parent" ? parentPathFor(item, byId) : group === "assignee" ? assigneeText(item) : group === "state" ? stateLabel[item.state] : "전체 작업"; all.set(key, [...(all.get(key) ?? []), item]); return all; }, new Map()), [shown, group, byId]);
  const row = (item: PlanItem) => <tr key={item.id}><td data-label="작업"><button className="plan-title" type="button" onClick={() => onOpen(item)}>{item.title}</button><ItemBadge item={item} /></td><td data-label="상위 경로">{pathFor(item, byId)}</td><td data-label="담당자"><select aria-label={`${item.title} 담당자`} disabled={!canEdit} value={item.assigneeId ?? ""} onChange={(e) => onQuickEdit(item, "assigneeId", e.target.value)}><option value="">미배정</option>{members.filter((member) => member.role === "MANAGER" || member.role === "MEMBER").map((member) => <option key={member.userId} value={member.userId}>{member.displayName || member.email || member.userId}</option>)}</select></td><td data-label="상태"><select aria-label={`${item.title} 상태`} disabled={!canEdit} value={item.state} onChange={(e) => onQuickEdit(item, "state", e.target.value)}>{states.map((state) => <option key={state} value={state}>{stateLabel[state]}</option>)}</select></td><td data-label="대상 기간"><label>시작<input aria-label={`${item.title} 시작일`} type="date" disabled={!canEdit} value={item.targetStart ?? ""} onChange={(e) => onQuickEdit(item, "targetStart", e.target.value)} /></label><label>종료<input aria-label={`${item.title} 종료일`} type="date" disabled={!canEdit} value={item.targetEnd ?? ""} onChange={(e) => onQuickEdit(item, "targetEnd", e.target.value)} /></label></td><td data-label="마감"><input aria-label={`${item.title} 마감일`} type="date" disabled={!canEdit} value={item.deadline ?? ""} onChange={(e) => onQuickEdit(item, "deadline", e.target.value)} /></td><td data-label="선행·차단">{item.predecessorIds.length ? `선행 ${item.predecessorIds.length}` : "선행 없음"}{item.blockerIds.length ? ` · 차단 ${item.blockerIds.length}` : ""}</td><td data-label="동작"><button className="text-button" type="button" onClick={() => onOpen(item)}>세부 정보</button></td></tr>;
  return <><div className="plan-list-controls"><label>정렬<select value={sort} onChange={(e) => { setSort(e.target.value); setPage(0); }}><option value="state">상태 우선</option><option value="deadline">마감일</option><option value="title">제목</option></select></label><label>그룹<select value={group} onChange={(e) => { setGroup(e.target.value); setPage(0); }}><option value="none">없음</option><option value="parent">상위 경로</option><option value="assignee">담당자</option><option value="state">상태</option></select></label></div><div className="plan-semantic-table-wrap"><table className="plan-semantic-table"><caption className="sr-only">작업 목록</caption><thead><tr><th>작업</th><th>상위 경로</th><th>담당자</th><th>상태</th><th>대상 기간</th><th>마감</th><th>선행·차단</th><th>동작</th></tr></thead><tbody>{Array.from(groups.entries()).flatMap(([name, groupRows]) => [group !== "none" ? <tr className="plan-group-row" key={`group-${name}`}><th colSpan={8} scope="rowgroup">{name} <small>{groupRows.length}건</small></th></tr> : null, ...groupRows.map(row)])}</tbody></table></div>{rows.length > 50 && <div className="pagination"><button disabled={!page} onClick={() => setPage(page - 1)}>이전</button><span>{page * 50 + 1}–{Math.min((page + 1) * 50, rows.length)} / {rows.length}</span><button disabled={(page + 1) * 50 >= rows.length} onClick={() => setPage(page + 1)}>다음</button></div>}</>;
}

function Board({ items, onOpen, onQuickEdit, canEdit }: { items: PlanItem[]; onOpen: (item: PlanItem) => void; onQuickEdit: (item: PlanItem, field: "title" | "state" | "targetStart" | "targetEnd" | "deadline", value: string) => void; canEdit: boolean }) {
  return <div className="plan-board">{states.filter((state) => state !== "CANCELLED").map((state) => <section key={state} aria-labelledby={`board-${state}`}><h2 id={`board-${state}`}>{stateLabel[state]} <small>{items.filter((item) => item.kind === "TASK" && item.state === state).length}</small></h2>{items.filter((item) => item.kind === "TASK" && item.state === state).map((item) => <article className="plan-card" key={item.id}><button type="button" onClick={() => onOpen(item)}>{item.title}</button><ItemBadge item={item} /><select aria-label={`${item.title} 상태`} disabled={!canEdit} value={item.state} onChange={(e) => onQuickEdit(item, "state", e.target.value)}>{states.map((candidate) => <option key={candidate} value={candidate}>{stateLabel[candidate]}</option>)}</select><small>{dateText(item.deadline)}</small></article>)}</section>)}</div>;
}

function Milestones({ items, allItems, byId, onOpen }: { items: PlanItem[]; allItems: PlanItem[]; byId: Map<string, PlanItem>; onOpen: (item: PlanItem) => void }) {
  const [page, setPage] = useState(0); const rows = items.filter((item) => item.kind === "MILESTONE"); const shown = rows.slice(page * 50, page * 50 + 50);
  useEffect(() => { if (page * 50 >= rows.length) setPage(Math.max(0, Math.ceil(rows.length / 50) - 1)); }, [page, rows.length]);
  return <><div className="plan-semantic-table-wrap"><table className="plan-semantic-table"><caption className="sr-only">Milestone 목록</caption><thead><tr><th>Milestone</th><th>상위 경로</th><th>담당자</th><th>목표일·기간·마감</th><th>상태</th><th>영향받는 미완료 TASK</th><th>그중 차단</th><th>변경일</th><th>동작</th></tr></thead><tbody>{shown.map((item) => { const impact = item.successorIds.map((id) => allItems.find((candidate) => candidate.id === id)).filter((candidate): candidate is PlanItem => !!candidate && candidate.kind === "TASK" && candidate.state !== "DONE" && candidate.state !== "CANCELLED"); const blocked = impact.filter((candidate) => candidate.state === "BLOCKED" || candidate.blockerIds.length); return <tr key={item.id}><td data-label="Milestone"><button className="plan-title" onClick={() => onOpen(item)}>{item.title}</button><ItemBadge item={item} /></td><td data-label="상위 경로">{parentPathFor(item, byId)}</td><td data-label="담당자">{assigneeText(item)}</td><td data-label="목표일·기간·마감">목표 {dateText(item.targetStart)} – {dateText(item.targetEnd)} · 마감 {dateText(item.deadline)}</td><td data-label="상태">{stateLabel[item.state]}</td><td data-label="영향받는 미완료 TASK">{impact.length ? impact.map((task) => task.title).join(", ") : "없음"}</td><td data-label="그중 차단">{blocked.length}</td><td data-label="변경일">{item.updatedAt ? new Date(item.updatedAt).toLocaleString("ko-KR") : "기록 없음"}</td><td data-label="동작"><button className="text-button" onClick={() => onOpen(item)}>세부 정보</button></td></tr>; })}</tbody></table></div>{rows.length > 50 && <div className="pagination"><button disabled={!page} onClick={() => setPage(page - 1)}>이전</button><span>{page * 50 + 1}–{Math.min((page + 1) * 50, rows.length)} / {rows.length}</span><button disabled={(page + 1) * 50 >= rows.length} onClick={() => setPage(page + 1)}>다음</button></div>}</>;
}

function MonthCalendar({ projectId, snapshot, query, canEdit, onOpen, onCreate }: { projectId: string; snapshot: PlanSnapshot; query: URLSearchParams; canEdit: boolean; onOpen: (item: PlanItem) => void; onCreate: (date: string) => void }) {
  const localMonth = () => { const now = new Date(); return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`; };
  const requestedMonth = query.get("month") ?? ""; const month = /^\d{4}-(0[1-9]|1[0-2])$/.test(requestedMonth) ? requestedMonth : localMonth();
  const selectedPlanTypes = effectivePlanTypes(query, "calendar");
  const [overflow, setOverflow] = useState<{ date: string; entries: PlanItem[] } | null>(null);
  const [year, monthNumber] = month.split("-").map(Number); const first = new Date(Date.UTC(year, monthNumber - 1, 1)); const offset = (first.getUTCDay() + 6) % 7; const days = new Date(Date.UTC(year, monthNumber, 0)).getUTCDate();
  const appointmentVisible = query.get("types")?.split(",").includes("APPOINTMENT") ?? false;
  const [schedulePage, setSchedulePage] = useState(0);
  useEffect(() => setSchedulePage(0), [month]);
  const nextMonthDate = new Date(Date.UTC(year, monthNumber, 1));
  const nextMonth = `${nextMonthDate.getUTCFullYear()}-${String(nextMonthDate.getUTCMonth() + 1).padStart(2, "0")}`;
  const rangeStart = localDateTimeToUtc(`${month}-01T00:00`, "Asia/Seoul");
  const rangeEnd = localDateTimeToUtc(`${nextMonth}-01T00:00`, "Asia/Seoul");
  const schedules = useQuery({ queryKey: [...keys.schedules(projectId), "plan-overlay", month, schedulePage], queryFn: () => api.schedules(projectId, rangeStart, rangeEnd, schedulePage), enabled: appointmentVisible });
  const setCalendar = (values: Record<string, string>) => setQuery(projectId, { ...Object.fromEntries(query.entries()), ...values });
  const entriesFor = (date: string) => snapshot.items.filter((item) => selectedPlanTypes.includes(item.kind) && (() => { const start = item.targetStart || item.targetEnd; const end = item.targetEnd || item.targetStart; return !!((start && end && date >= start && date <= end) || item.deadline === date); })());
  const shift = (delta: number) => { const date = new Date(Date.UTC(year, monthNumber - 1 + delta, 1)); setCalendar({ month: date.toISOString().slice(0, 7) }); };
  const scheduleEntries = schedules.data ?? [];
  return <section className="plan-calendar"><div className="calendar-toolbar"><button type="button" onClick={() => shift(-1)}>이전 달</button><label>월<input type="month" value={month} onChange={(e) => setCalendar({ month: e.target.value })} /></label><button type="button" onClick={() => setCalendar({ month: localMonth() })}>오늘</button><button type="button" onClick={() => shift(1)}>다음 달</button><label className="check-label"><input type="checkbox" checked={appointmentVisible} onChange={(e) => { const selected = new Set((query.get("types")?.split(",").filter(Boolean) ?? defaultTypes.calendar)); if (e.target.checked) selected.add("APPOINTMENT"); else selected.delete("APPOINTMENT"); setCalendar({ types: Array.from(selected).join(",") }); }} /> 기존 일정 함께 보기</label></div>{appointmentVisible && <div className="appointment-overlay-status">{schedules.isPending && <p role="status">기존 일정을 불러오는 중…</p>}{schedules.isError && <Notice error={schedules.error} message="기존 일정을 불러오지 못했다. 계획 항목은 계속 표시한다." />}{!schedules.isPending && !schedules.isError && <p>{schedulePage + 1}페이지의 기존 일정 {scheduleEntries.length}건</p>}<div className="pagination"><button type="button" disabled={schedulePage === 0 || schedules.isFetching} onClick={() => setSchedulePage((value) => value - 1)}>이전 일정</button><button type="button" disabled={scheduleEntries.length < 20 || schedules.isFetching} onClick={() => setSchedulePage((value) => value + 1)}>다음 일정</button></div></div>}<div className="calendar-weekdays" aria-hidden="true">{["월", "화", "수", "목", "금", "토", "일"].map((day) => <span key={day}>{day}</span>)}</div><div className="month-grid plan-month-grid">{Array.from({ length: offset + days }, (_, index) => { const day = index - offset + 1; const date = day > 0 ? `${month}-${String(day).padStart(2, "0")}` : ""; const dayEntries = date ? entriesFor(date) : []; const daySchedules = date && appointmentVisible ? scheduleEntries.filter((schedule) => dateInZone(schedule.startsAt, "Asia/Seoul") <= date && dateInZone(new Date(Date.parse(schedule.endsAt) - 1).toISOString(), "Asia/Seoul") >= date) : []; const shown = dayEntries.slice(0, 3); return <div key={`${month}-${index}`} className={day > 0 ? "" : "is-outside"}>{day > 0 && <time dateTime={date}>{day}</time>}{shown.map((item) => <button key={`${item.id}-${date}`} type="button" onClick={() => onOpen(item)}><span className="calendar-entry-title">{item.title}<small className="calendar-date-meaning">{item.deadline === date ? "마감" : "목표 기간"}</small></span><ItemBadge item={item} /></button>)}{daySchedules.map((schedule) => <Link key={`schedule-${schedule.id}-${date}`} className="calendar-appointment" to={`/projects/${projectId}/schedules/${schedule.id}`}><span>기존 일정 · 읽기 전용</span>{schedule.title}</Link>)}{dayEntries.length > shown.length && <button type="button" className="calendar-more" onClick={() => setOverflow({ date, entries: dayEntries })}>{dayEntries.length - shown.length}개 더 보기</button>}{date && <button type="button" disabled={!canEdit} className="calendar-create" onClick={() => onCreate(date)}><Icon name="plus" className="plan-icon" />이 날짜에 TASK 추가</button>}</div>; })}</div>{overflow && <Dialog open title={`${overflow.date} 항목`} onClose={() => setOverflow(null)}><ul className="calendar-overflow">{overflow.entries.map((item) => <li key={item.id}><button type="button" onClick={() => { setOverflow(null); onOpen(item); }}>{item.title}<ItemBadge item={item} /></button></li>)}</ul></Dialog>}</section>;
}

export function ProjectTargetEditor({ projectId, snapshot, canEdit, onForbidden }: { projectId: string; snapshot: PlanSnapshot; canEdit: boolean; onForbidden: () => void }) {
  const qc = useQueryClient();
  const [open, setOpen] = useState(false);
  const [start, setStart] = useState(snapshot.targetStart ?? "");
  const [end, setEnd] = useState(snapshot.targetEnd ?? "");
  const [version, setVersion] = useState(snapshot.rowVersion);
  const [baseline, setBaseline] = useState({ start: snapshot.targetStart ?? "", end: snapshot.targetEnd ?? "", version: snapshot.rowVersion });
  const [conflict, setConflict] = useState<PlanSnapshot | null>(null);
  const dirty = open && (start !== baseline.start || end !== baseline.end);
  const guard = useUnsavedChanges(dirty);
  const close = () => { if (guard.confirmDiscard()) { setStart(baseline.start); setEnd(baseline.end); setVersion(baseline.version); setConflict(null); setOpen(false); } };
  const save = useMutation({ mutationFn: (retryVersion?: number) => api.savePlan(projectId, { rowVersion: retryVersion ?? version, targetStart: start || null, targetEnd: end || null }), onMutate: captureSession, onSuccess: async (_value, _vars, context) => { if (!isSessionContextActive(context)) return; guard.markSaved(); await qc.invalidateQueries({ queryKey: ["project-plan", projectId] }); setOpen(false); setConflict(null); }, onError: async (error) => { if (error instanceof ApiError && error.status === 403) { onForbidden(); return; } if (error instanceof ApiError && error.status === 409) { try { const latest = await api.plan(projectId); setConflict(latest); } catch { /* preserve the proposed dates when the latest read fails */ } } } });
  useEffect(() => { if (!open) { const next = { start: snapshot.targetStart ?? "", end: snapshot.targetEnd ?? "", version: snapshot.rowVersion }; setBaseline(next); setStart(next.start); setEnd(next.end); setVersion(next.version); } }, [snapshot.targetStart, snapshot.targetEnd, snapshot.rowVersion, open]);
  return <section className="plan-target"><div><span>프로젝트 수동 목표 기간</span><strong>{dateText(snapshot.targetStart)} – {dateText(snapshot.targetEnd)}</strong><small>예상 기간은 TASK 날짜로 별도 계산한다.</small></div>{canEdit && <button type="button" onClick={() => open ? close() : setOpen(true)}>{open ? "닫기" : "목표일 편집"}</button>}{open && <form onSubmit={(e) => { e.preventDefault(); if (!save.isPending) save.mutate(undefined); }}><label>시작일<input type="date" value={start} disabled={!canEdit} onChange={(e) => setStart(e.target.value)} /></label><label>종료일<input type="date" value={end} disabled={!canEdit} onChange={(e) => setEnd(e.target.value)} /></label><button type="button" onClick={close}>취소</button><button className="button-primary" type="submit" disabled={!canEdit || save.isPending}>{save.isPending ? "저장 중…" : "저장"}</button>{conflict && <div className="plan-conflict" role="alert"><strong>프로젝트 목표가 변경되었다.</strong><p>내 입력은 보존되어 있다. 최신 목표는 {dateText(conflict.targetStart)} – {dateText(conflict.targetEnd)}다.</p><button type="button" onClick={() => { setVersion(conflict.rowVersion); setConflict(null); save.mutate(conflict.rowVersion); }}>내 입력을 최신 version으로 재시도</button><button type="button" onClick={() => { const next = { start: conflict.targetStart ?? "", end: conflict.targetEnd ?? "", version: conflict.rowVersion }; setBaseline(next); setStart(next.start); setEnd(next.end); setVersion(next.version); setConflict(null); }}>최신값 적용</button></div>}{save.isError && !conflict && <Notice error={save.error} />}</form>}</section>;
}

export function ProjectPlan({ id }: { id: string }) {
  const qc = useQueryClient(); const project = useProject(id); const [route, setRoute] = useState(readQuery); const [editor, setEditor] = useState<PlanItem | null | undefined>(undefined); const [editorKind, setEditorKind] = useState<PlanKind>("TASK"); const [createKind, setCreateKind] = useState<PlanKind>("TASK"); const [editorDraft, setEditorDraft] = useState<PlanItemWrite | undefined>(); const [editorRecovery, setEditorRecovery] = useState<string | undefined>(); const [detail, setDetail] = useState<PlanItem | null>(null); const [notice, setNotice] = useState(""); const [writeDenied, setWriteDenied] = useState(false); const [searchDraft, setSearchDraft] = useState(""); const [advancedOpen, setAdvancedOpen] = useState(false);
  useEffect(() => { const sync = () => setRoute(readQuery()); window.addEventListener("hashchange", sync); return () => window.removeEventListener("hashchange", sync); }, []);
  const routeSearch = route.query.get("q") ?? "";
  useEffect(() => { setSearchDraft(routeSearch); }, [routeSearch]);
  useEffect(() => { const selected = effectivePlanTypes(route.query, route.view); setCreateKind(selected.length === 1 ? selected[0] : viewDefaultKind[route.view]); }, [route.view, route.query.toString()]);
  useEffect(() => { const timeout = window.setTimeout(() => { if (searchDraft !== routeSearch) { const current = readQuery().query; if (searchDraft) current.set("q", searchDraft); else current.delete("q"); setQuery(id, Object.fromEntries(current.entries()), true); } }, 300); return () => window.clearTimeout(timeout); }, [id, searchDraft, routeSearch]);
  const query = useQuery({ queryKey: keys.plan(id, queryString(route.query, route.view)), queryFn: () => api.plan(id, queryString(route.query, route.view)), enabled: project.isSuccess && !!project.data });
  const members = useQuery({ queryKey: keys.members(id), queryFn: () => api.members(id), enabled: project.isSuccess && !!project.data });
  const canEdit = !writeDenied && (project.data?.role === "MANAGER" || project.data?.role === "MEMBER");
  const rawItems = query.data?.items ?? []; const items = useMemo(() => rawItems.map((item) => ({ ...item, assigneeName: members.data?.find((member) => member.userId === item.assigneeId)?.displayName || members.data?.find((member) => member.userId === item.assigneeId)?.email || null })), [members.data, rawItems]); const byId = useMemo(() => new Map(items.map((item) => [item.id, item])), [items]); const matched = useMemo(() => new Set(query.data?.matchedIds ?? items.map((item) => item.id)), [items, query.data?.matchedIds]); const visibleItems = items.filter((item) => matched.has(item.id));
  const deny = async () => { setWriteDenied(true); setDetail(null); setEditor(undefined); setEditorDraft(undefined); setEditorRecovery(undefined); qc.removeQueries({ queryKey: ["project-plan", id] }); qc.removeQueries({ queryKey: keys.members(id) }); await project.refetch(); setNotice("계획 권한이 변경되어 편집을 잠갔습니다. 현재 권한을 다시 확인했다."); };
  useEffect(() => { if (query.error instanceof ApiError && (query.error.status === 403 || query.error.status === 404)) void deny(); }, [query.error]);
  const update = useMutation({ mutationFn: ({ item, field, value }: { item: PlanItem; field: string; value: string }) => { const body: PlanItemWrite = { parentId: item.parentId, kind: item.kind, title: item.title, description: item.description ?? "", assigneeId: item.assigneeId, state: item.state, targetStart: item.targetStart, targetEnd: item.targetEnd, deadline: item.deadline, sortOrder: item.sortOrder, labels: item.labels, predecessorIds: item.predecessorIds, rowVersion: item.rowVersion }; if (field === "title") body.title = value; if (field === "state") body.state = value as PlanState; if (field === "assigneeId") body.assigneeId = value || null; if (field === "targetStart") body.targetStart = value || null; if (field === "targetEnd") body.targetEnd = value || null; if (field === "deadline") body.deadline = value || null; if (field === "sortOrder") body.sortOrder = Number(value); return api.updatePlanItem(id, item.id, body); }, onMutate: captureSession, onSuccess: async (_value, _variables, context) => { if (!isSessionContextActive(context)) return; setNotice("계획 항목을 저장했습니다."); await query.refetch(); }, onError: async (error, variables) => { if (error instanceof ApiError && error.status === 403) { await deny(); return; } if (error instanceof ApiError && error.status === 409) { try { const latestSnapshot = await api.plan(id); const latest = latestSnapshot.items.find((candidate) => candidate.id === variables.item.id); if (latest) { const latestDraft: PlanItemWrite = { parentId: latest.parentId, kind: latest.kind, title: latest.title, description: latest.description ?? "", assigneeId: latest.assigneeId, state: latest.state, targetStart: latest.targetStart, targetEnd: latest.targetEnd, deadline: latest.deadline, sortOrder: latest.sortOrder, labels: latest.labels, predecessorIds: latest.predecessorIds, rowVersion: latest.rowVersion }; if (variables.field === "title") latestDraft.title = variables.value; if (variables.field === "state") latestDraft.state = variables.value as PlanState; if (variables.field === "assigneeId") latestDraft.assigneeId = variables.value || null; if (variables.field === "targetStart") latestDraft.targetStart = variables.value || null; if (variables.field === "targetEnd") latestDraft.targetEnd = variables.value || null; if (variables.field === "deadline") latestDraft.deadline = variables.value || null; if (variables.field === "sortOrder") latestDraft.sortOrder = Number(variables.value); setEditorDraft(latestDraft); setEditorRecovery("내가 바꾼 한 필드만 최신 항목에 반영했다. 최신 설명, 담당자와 다른 필드는 유지된다. 내용을 확인한 뒤 저장한다."); setEditorKind(latest.kind); setEditor(latest); setNotice("다른 구성원이 먼저 변경했다. 최신 항목에 내 변경 한 건만 반영해 편집 화면을 열었다."); return; } } catch { /* retain the recovery notice if the latest read fails */ } } setNotice("계획 항목을 저장하지 못했습니다."); } });
  const scopeItem = route.query.get("scopeId") ? byId.get(route.query.get("scopeId")!) : undefined;
  const createParentId = scopeItem && validParent(createKind, scopeItem) ? scopeItem.id : null;
  const assignableMembers = (members.data ?? []).filter((member) => member.role === "MANAGER" || member.role === "MEMBER");
  const selectedTypes = (route.query.get("types") ?? route.query.get("kind"))?.split(",").filter(Boolean) ?? defaultTypes[route.view];
  const hierarchyShowLeaves = selectedTypes.some((kind) => kind === "TASK" || kind === "MILESTONE");
  const supportedTypes = route.view === "tasks" || route.view === "board" ? ["TASK"] : route.view === "milestones" ? ["MILESTONE"] : route.view === "hierarchy" ? ["EPIC", "TOPIC"] : kinds;
  const hiddenTypes = selectedTypes.filter((kind) => kind !== "APPOINTMENT" && !supportedTypes.includes(kind as PlanKind));
  const hasPlanFilters = ["q", "types", "kind", "state", "assigneeId", "label", "from", "to", "unassigned", "includeCancelled"].some((key) => route.query.has(key));
  const applyFilter = (key: string, value: string | null) => { const next = new URLSearchParams(route.query); if (value) next.set(key, value); else next.delete(key); setQuery(id, Object.fromEntries(next.entries()), true); };
  const applyTypes = (value: string | null) => { const appointment = route.query.get("types")?.split(",").includes("APPOINTMENT"); const next = new URLSearchParams(route.query); next.delete("kind"); const nextValue = [value, appointment ? "APPOINTMENT" : null].filter(Boolean).join(","); if (nextValue) next.set("types", nextValue); else next.delete("types"); setQuery(id, Object.fromEntries(next.entries()), true); };
  const resetFilters = () => { const next = new URLSearchParams(route.query); ["q", "types", "kind", "state", "from", "to", "assigneeId", "label", "unassigned", "includeCancelled"].forEach((key) => next.delete(key)); setQuery(id, Object.fromEntries(next.entries()), true); };
  const createDraftFor = (kind: PlanKind, date?: string): PlanItemWrite => { const from = date ?? route.query.get("from") ?? null; const to = date ?? route.query.get("to") ?? null; const scopedParent = scopeItem && validParent(kind, scopeItem) ? scopeItem.id : null; const filteredAssignee = route.query.get("assigneeId"); const assigneeId = assignableMembers.some((member) => member.userId === filteredAssignee) ? filteredAssignee : null; return { parentId: scopedParent, kind, title: "", description: "", assigneeId, state: "BACKLOG", targetStart: from, targetEnd: to || from, deadline: null, sortOrder: 0, labels: [], predecessorIds: [], requestId: randomId() }; };
  const openCreate = (kind = createKind, date?: string) => { setEditorDraft(createDraftFor(kind, date)); setEditorKind(kind); setEditor(null); };
  if (!project.isSuccess) return <Shell><QueryState query={project} /></Shell>;
  if (!project.data) return <Shell><ProjectMissing onRetry={() => project.refetch()} isFetching={project.isFetching} /></Shell>;
  return <Shell project={project.data} workspace><div className="plan-screen"><header className="page-heading"><div><p className="eyebrow">{project.data.name}</p><h1>계획</h1><p className="lead">프로젝트 구조와 실행 항목을 빠르게 찾고 관리한다.</p>{scopeItem && <p className="plan-breadcrumb">범위: {pathFor(scopeItem, byId)} <button type="button" className="text-button" onClick={() => setQuery(id, { scopeId: null })}>프로젝트 전체로 이동</button></p>}</div><div className="action-row"><label className="create-kind">종류<select aria-label="새 항목 종류" value={createKind} disabled={!canEdit} onChange={(e) => setCreateKind(e.target.value as PlanKind)}>{kinds.map((kind) => <option key={kind} value={kind}>{kindLabel[kind]}</option>)}</select></label><button className="button button-primary" disabled={!canEdit || !!scopeItem && !validParent(createKind, scopeItem)} onClick={() => openCreate()}><Icon name="plus" className="plan-icon" />항목 추가</button></div></header>
    <nav className="plan-view-nav" aria-label="계획 보기"><label className="plan-view-select">보기<select aria-label="계획 보기" value={route.view} onChange={(event) => setQuery(id, { ...Object.fromEntries(route.query.entries()), view: event.target.value })}>{views.map(([view, label]) => <option key={view} value={view}>{label}</option>)}</select></label>{views.map(([view, label]) => <Link key={view} to={`/projects/${id}/plan?${new URLSearchParams({ ...Object.fromEntries(route.query.entries()), view }).toString()}`} aria-current={route.view === view ? "page" : undefined}>{label}</Link>)}</nav>
    <section className="plan-filter-bar" aria-label="계획 필터"><div className="plan-filter-primary"><label><span className="filter-label"><Icon name="search" className="plan-icon" />검색</span><input aria-label="검색" name="q" value={searchDraft} onChange={(e) => setSearchDraft(e.target.value)} placeholder="제목·설명 검색" /></label><label>종류<select name="types" value={(route.query.get("types") ?? route.query.get("kind") ?? "").split(",").filter((value) => value !== "APPOINTMENT").join(",")} onChange={(e) => applyTypes(e.target.value || null)}><option value="">이 보기의 기본 유형</option><option value="EPIC,TOPIC,TASK,MILESTONE">전체 계획 유형</option><option value="EPIC,TOPIC">EPIC + TOPIC</option><option value="TASK,MILESTONE">TASK + Milestone</option>{kinds.map((kind) => <option key={kind} value={kind}>{kindLabel[kind]}</option>)}</select></label><label>상태<select value={route.query.get("state") ?? ""} onChange={(e) => applyFilter("state", e.target.value || null)}><option value="">전체 상태</option>{states.map((state) => <option key={state} value={state}>{stateLabel[state]}</option>)}</select></label><label>담당자<select value={route.query.get("assigneeId") ?? ""} onChange={(e) => applyFilter("assigneeId", e.target.value || null)}><option value="">전체 담당자</option>{assignableMembers.map((member) => <option key={member.userId} value={member.userId}>{member.displayName || member.email}</option>)}</select></label><button type="button" className="filter-advanced-toggle" aria-expanded={advancedOpen} onClick={() => setAdvancedOpen((value) => !value)}><Icon name="filter" className="plan-icon" />상세 필터</button></div>{advancedOpen && <div className="plan-filter-advanced"><label>레이블<input value={route.query.get("label") ?? ""} placeholder="레이블" onChange={(e) => applyFilter("label", e.target.value || null)} /></label><label>시작<input type="date" value={route.query.get("from") ?? ""} onChange={(e) => applyFilter("from", e.target.value || null)} /></label><label>종료<input type="date" value={route.query.get("to") ?? ""} onChange={(e) => applyFilter("to", e.target.value || null)} /></label><label className="check-label"><input type="checkbox" checked={route.query.get("unassigned") === "true"} onChange={(e) => applyFilter("unassigned", e.target.checked ? "true" : null)} /> 미배정만</label><label className="check-label"><input type="checkbox" checked={route.query.get("includeCancelled") === "true"} onChange={(e) => applyFilter("includeCancelled", e.target.checked ? "true" : null)} /> 취소 포함</label></div>}<div className="filter-chips" aria-live="polite">{route.query.get("q") && <button type="button" onClick={() => { setSearchDraft(""); applyFilter("q", null); }}>검색: {route.query.get("q")} ×</button>}{(route.query.get("types") || route.query.get("kind")) && <button type="button" onClick={() => setQuery(id, { ...Object.fromEntries(route.query.entries()), types: null, kind: null }, true)}>종류: {selectedTypes.filter((value) => value !== "APPOINTMENT").map((value) => kindLabel[value as PlanKind] ?? value).join(", ")} ×</button>}{route.query.get("state") && <button type="button" onClick={() => applyFilter("state", null)}>상태: {stateLabel[route.query.get("state") as PlanState]} ×</button>}{route.query.get("assigneeId") && <button type="button" onClick={() => applyFilter("assigneeId", null)}>담당자 조건 ×</button>}{route.query.get("from") && <button type="button" onClick={() => applyFilter("from", null)}>시작: {route.query.get("from")} ×</button>}{route.query.get("to") && <button type="button" onClick={() => applyFilter("to", null)}>종료: {route.query.get("to")} ×</button>}{route.query.get("label") && <button type="button" onClick={() => applyFilter("label", null)}>레이블: {route.query.get("label")} ×</button>}{route.query.get("unassigned") === "true" && <button type="button" onClick={() => applyFilter("unassigned", null)}>미배정만 ×</button>}{route.query.get("includeCancelled") === "true" && <button type="button" onClick={() => applyFilter("includeCancelled", null)}>취소 포함 ×</button>}{hasPlanFilters && <button type="button" onClick={resetFilters}>전체 초기화</button>}</div></section>{hiddenTypes.length > 0 && <p className="help" role="status">선택한 {hiddenTypes.map((kind) => kindLabel[kind as PlanKind]).join(", ")} 유형은 이 관점에서 표시되지 않는다. 선택은 다른 관점으로 이동해도 유지된다.</p>}
    {notice && <p className="plan-live" role="status">{notice}</p>}{query.isError && <QueryState query={query} errorMessage="계획을 불러오지 못했습니다." />}{query.isFetching && query.data && <p className="help" role="status">최신 계획을 불러오는 중…</p>}{query.data && <><details className="plan-context"><summary>목표·집계 보기 <span className="plan-snapshot-meta">전체 {query.data.totalCount}개 항목 · 필터 항목 {query.data.matchedIds.length}개</span></summary><ProjectTargetEditor projectId={id} snapshot={query.data} canEdit={!!canEdit} onForbidden={() => void deny()} /><Summary label="전체 프로젝트" summary={query.data.summary} />{route.query.get("scopeId") && <Summary label="선택 항목 하위" summary={byId.get(route.query.get("scopeId")!)?.summary ?? emptySummary} />}<p className="plan-snapshot-meta">전체 {query.data.totalCount}개 항목 · 기준일 {query.data.asOfDate} · 필터 항목 {query.data.matchedIds.length}개</p></details><div className="plan-content">{route.view === "roadmap" && <Roadmap items={visibleItems} byId={byId} onOpen={setDetail} />}{route.view === "hierarchy" && <Hierarchy items={visibleItems} byId={byId} showLeaves={hierarchyShowLeaves} onShowLeaves={(value) => setQuery(id, { types: value ? kinds.join(",") : null, kind: null })} onOpen={setDetail} canEdit={!!canEdit} onScope={(scopeId) => setQuery(id, { view: route.view, scopeId })} onQuickEdit={(item, field, value) => update.mutate({ item, field, value })} />}{route.view === "tasks" && <Tasks items={visibleItems} byId={byId} members={members.data ?? []} onOpen={setDetail} canEdit={!!canEdit} onQuickEdit={(item, field, value) => update.mutate({ item, field, value })} />}{route.view === "board" && <Board items={visibleItems} onOpen={setDetail} canEdit={!!canEdit} onQuickEdit={(item, field, value) => update.mutate({ item, field, value })} />}{route.view === "milestones" && <Milestones items={visibleItems} allItems={items} byId={byId} onOpen={setDetail} />}{route.view === "calendar" && <MonthCalendar projectId={id} query={route.query} canEdit={!!canEdit && !(scopeItem && !validParent("TASK", scopeItem))} snapshot={{ ...query.data, items: visibleItems, matchedIds: visibleItems.map((item) => item.id) }} onOpen={setDetail} onCreate={(date) => openCreate("TASK", date)} />}</div></>}
    {editor !== undefined && <ItemEditor projectId={id} item={editor} items={items} canEdit={!!canEdit} initialKind={editorKind} initialParentId={createParentId} initialDraft={editorDraft} recoveryMessage={editorRecovery} onClose={() => { setEditor(undefined); setEditorDraft(undefined); setEditorRecovery(undefined); }} onSaved={() => { setEditor(undefined); setEditorDraft(undefined); setEditorRecovery(undefined); }} onForbidden={() => void deny()} />}<DetailDialog projectId={id} item={detail} items={items} members={members.data ?? []} canEdit={!!canEdit} onClose={() => setDetail(null)} onEdit={() => { setEditorDraft(undefined); setEditorRecovery(undefined); setEditorKind(detail?.kind ?? "TASK"); setEditor(detail); setDetail(null); }} onNavigate={(next) => setDetail(next)} />
  </div></Shell>;
}
